import{_ as a}from"./chunks/position_fixed.t2m3lWVy.js";import{_ as t,c as o,al as i,o as r}from"./chunks/framework.DCERqlYr.js";const p=JSON.parse('{"title":"Режим Місії (VTOL)","description":"","frontmatter":{},"headers":[],"relativePath":"uk/flight_modes_vtol/mission.md","filePath":"uk/flight_modes_vtol/mission.md"}'),n={name:"uk/flight_modes_vtol/mission.md"};function s(l,e,m,_,h,d){return r(),o("div",null,e[0]||(e[0]=[i('<h1 id="режим-місіі-vtol" tabindex="-1">Режим Місії (VTOL) <a class="header-anchor" href="#режим-місіі-vtol" aria-label="Permalink to &quot;Режим Місії (VTOL)&quot;">​</a></h1><img src="'+a+'" title="Global position fix required (e.g. GPS)" width="30px"><p><em>Режим місії</em> змушує транспортний засіб виконувати передбачений автономний <a href="./../flying/missions.html">план місії</a> (план польоту), який був завантажений до керуючого пристрою польоту. Зазвичай місія створюється та завантажується за допомогою програми для керування наземною станцією (GCS), такої як <a href="https://docs.qgroundcontrol.com/master/en/" target="_blank" rel="noreferrer">QGroundControl</a> (QGC).</p><p>VTOL-транспортні засоби дотримуються поведінки та параметрів фіксованих крил під час перебування у режимі FW, і багтроторних апаратів у режимі MC. Для отримання додаткової інформації дивіться конкретні документи для кожного режиму:</p><ul><li><a href="./../flight_modes_mc/mission.html">Режим Місії (MC)</a></li><li><a href="./../flight_modes_fw/mission.html">Режим Місії (FW)</a></li></ul><p>У наступних розділах описується поведінка режиму місії, яка є специфічною для VTOL.</p><h2 id="команди-місіи" tabindex="-1">Команди місій <a class="header-anchor" href="#команди-місіи" aria-label="Permalink to &quot;Команди місій&quot;">​</a></h2><p>Наступні команди VTOL відповідають специфікації MAVLink.</p><ul><li><a href="https://mavlink.io/en/messages/common.html#MAV_CMD_NAV_VTOL_TAKEOFF" target="_blank" rel="noreferrer">MAV_CMD_NAV_VTOL_TAKEOFF</a><ul><li><code>MAV_CMD_NAV_VTOL_TAKEOFF.param2</code> (заголовок переходу) ігнорується. Замість цього напрямок до наступної маршрутної точки використовується для переходу. </li></ul></li><li><a href="https://mavlink.io/en/messages/common.html#MAV_CMD_NAV_VTOL_LAND" target="_blank" rel="noreferrer">MAV_CMD_NAV_VTOL_LAND</a></li><li><a href="https://mavlink.io/en/messages/common.html#MAV_CMD_DO_VTOL_TRANSITION" target="_blank" rel="noreferrer">MAV_CMD_DO_VTOL_TRANSITION</a></li></ul><p>В іншому випадку PX4 зазвичай &quot;приймає&quot; команди місії для фіксованого крила або мультикоптера у відповідних режимах.</p><p>У режимі фіксованого крила є наступні винятки:</p><ul><li><a href="https://mavlink.io/en/messages/common.html#MAV_CMD_NAV_LAND" target="_blank" rel="noreferrer">MAV_CMD_NAV_LAND</a> перетворюється на <a href="https://mavlink.io/en/messages/common.html#MAV_CMD_NAV_VTOL_LAND" target="_blank" rel="noreferrer">MAV_CMD_NAV_VTOL_LAND</a> якщо <a href="./../advanced_config/parameter_reference.html#NAV_FORCE_VT">NAV_FORCE_VT</a> встановлено на <code>0</code> (вимкнено).</li><li><a href="https://mavlink.io/en/messages/common.html#MAV_CMD_NAV_TAKEOFF" target="_blank" rel="noreferrer">MAV_CMD_NAV_TAKEOFF</a> не підтримується.</li></ul><h2 id="mission-command-timeouts" tabindex="-1">Mission Command Timeouts <a class="header-anchor" href="#mission-command-timeouts" aria-label="Permalink to &quot;Mission Command Timeouts&quot;">​</a></h2><p>Some mission commands/items can take time to complete, such as a gripper opening and closing, a winch extending or retracting, or a gimbal moving to point at a region of interest.</p><p>Where provided PX4 may use sensor feedback from the hardware to determine when the action has completed and then move to the next mission item. If not provided, or if the feedback is lost, a mission command timeout can be used to ensure that these kinds of actions will progress to the next mission item rather than blocking progression.</p><p>The timeout is set using the <a href="./../advanced_config/parameter_reference.html#MIS_COMMAND_TOUT">MIS_COMMAND_TOUT</a> parameter. This should be set to be a small amount greater than the time required for the longest long-running action in the mission to complete.</p><h2 id="місія-зліт" tabindex="-1">Місія зліт <a class="header-anchor" href="#місія-зліт" aria-label="Permalink to &quot;Місія зліт&quot;">​</a></h2><p>Заплануйте зліт місії VTOL, додавши на карту пункт місії <code>VTOL Takeoff</code>.</p><p>Під час виконання місії транспортний засіб підніметься вертикально до мінімальної висоти взяття на озброєння, визначеної в параметрі <a href="./../advanced_config/parameter_reference.html#MIS_TAKEOFF_ALT">MIS_TAKEOFF_ALT</a>, а потім перейде в режим фіксованих крил з напрямком, визначеним у елементі місії. Після переходу транспортний засіб рухається в напрямку 3D-позиції, визначеної у елементі місії. Після переходу транспортний засіб рухається в напрямку 3D-позиції, визначеної у елементі місії.</p><p>Для взяття на озброєння місії <code>VTOL Takeoff</code> необхідно додати елемент місії Взліт VTOL (<code>MAV_CMD_NAV_VTOL_TAKEOFF</code>) для взяття на озброєння (або <code>MAV_CMD_NAV_TAKEOFF</code>, коли транспортний засіб перебуває у режимі MC); однак, якщо транспортний засіб вже знаходиться у повітрі, коли місія починається, елемент взяття на озброєння буде оброблено як звичайна точка маршруту.</p><h2 id="дивіться-також" tabindex="-1">Дивіться також <a class="header-anchor" href="#дивіться-також" aria-label="Permalink to &quot;Дивіться також&quot;">​</a></h2><ul><li><a href="./../flight_modes_mc/mission.html">Режим Місії (MC)</a></li><li><a href="./../flight_modes_fw/mission.html">Режим Місії (FW)</a></li><li><a href="./../flying/missions.html">Місії</a><ul><li><a href="./../flying/package_delivery_mission.html">Місія доставки посилок</a></li></ul></li></ul>',22)]))}const V=t(n,[["render",s]]);export{p as __pageData,V as default};
